def compute(vars):
    net = vars["v1"]
    gross = vars["v2"]
    if gross == 0:
        return None

    value = (net / gross) * 100
    return {
        "value": value,
        "trace": {
            "net": net,
            "gross": gross,
            "output_meta": {
                "currency": None,
                "scale": "ones",
                "unit": "percentage"
            }
        }
    }
